#include <vector>
using namespace std;

class Solution {
public:
    int surfaceArea(vector<vector<int>>& grid) {
        int area = 0, n = grid.size();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) {
                if (grid[i][j]) area += 6 * grid[i][j] - 2 * (grid[i][j] - 1);
                if (i) area -= 2 * min(grid[i][j], grid[i - 1][j]);
                if (j) area -= 2 * min(grid[i][j], grid[i][j - 1]);
            }
        return area;
    }
};
